// The eight star systems of Starlight Courier, in order of difficulty. Each level is plain
// data: where the ship starts, which planet takes the parcel, the gravity bodies, the moving
// comet hazards, the bonus shards, and the fuel and landing limits. Later levels add a sun,
// comets, tighter landings and less fuel — the same verbs, harder choices.
export const LEVELS = [
  {
    name: 'First Light',
    subtitle: '初光 · 第一单',
    hint: 'Drag to aim — release to launch. Land gently on the beacon planet.',
    ship: { x: 150, y: 560 },
    target: { x: 1120, y: 160, radius: 46, color: '#3fb8a6', name: 'Teal Harbor' },
    planets: [{ x: 620, y: 470, radius: 52, mass: 1100, color: '#3fb8a6', ring: false }],
    sun: null,
    comets: [],
    shards: [
      { x: 400, y: 300 },
      { x: 880, y: 430 },
      { x: 1020, y: 300 },
